mapper.select:
SELECT
${page.fields}
ASUM,BSUM,CSUM,REPORT_TIME,SERVICE,CFG_ID
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 1 THEN SUM ELSE 0 END) CSUM, PZ.REPORT_TIME, PZ.CFG_ID, PZ.SERVICE FROM DJ_PZ_REPORT PZ GROUP BY PZ.CFG_ID, PZ.SERVICE, PZ.REPORT_TIME ) DJ_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND CFG_ID =#{searchCfgId}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,SERVICE,CFG_ID
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.CFG_ID, PZ.SERVICE FROM DJ_PZ_REPORT PZ GROUP BY PZ.CFG_ID, PZ.SERVICE, PZ.REPORT_TIME ) DJ_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND CFG_ID =#{searchCfgId}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
CFG_ID,SERVICE,SUM
FROM (
SELECT CFG_ID,SERVICE, DECODE(ASUM,0,BSUM,ASUM) SUM FROM ( SELECT config_id CFG_ID, SERVICE, SUM(CASE WHEN ACTIVE_SYS=4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN ACTIVE_SYS=2 THEN SUM ELSE 0 END) BSUM FROM dj_stat_log_hour
AND stat_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND stat_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
GROUP BY config_id,SERVICE ) REPORT
SELECT config_id CFG_ID,SERVICE,SUM(sum) SUM FROM dj_stat_log_hour
AND stat_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND stat_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}
GROUP BY config_id,SERVICE
)
ORDER BY ${page.orderBy}

SELECT
${page.fields}
CFG_ID,SERVICE,SUM
FROM (
SELECT CFG_ID,SERVICE, DECODE(ASUM,0,BSUM,ASUM) SUM FROM ( SELECT CFG_ID, SERVICE, SUM(CASE WHEN ACTIVE_SYS=4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN ACTIVE_SYS=2 THEN SUM ELSE 0 END) BSUM FROM DJ_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
GROUP BY CFG_ID,SERVICE ) REPORT
SELECT CFG_ID,SERVICE,SUM(sum) SUM FROM DJ_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}
GROUP BY CFG_ID,SERVICE
)
ORDER BY ${page.orderBy}

SELECT SUM(sum) SUM FROM DJ_PZ_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND SERVICE =#{searchService}
AND active_sys=#{searchStatActiveSys}

SELECT
${page.fields}
ASUM,BSUM,absum,REPORT_TIME,ATTR_TYPE,SERVICE
FROM ( SELECT attr_type,REPORT_TIME, sum(asum) asum, sum(bsum) bsum, SUM(absum) absum,service FROM (select attr_type, asum, bsum, absum, REPORT_TIME,service from (select attr_type, REPORT_TIME,service, asum, bsum, decode(asum, 0, bsum, asum) absum from (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME, pz.cfg_id, pz.attr_type,pz.service FROM dj_pz_attr_report PZ
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND ATTR_TYPE =#{searchAttrType}
AND SERVICE =#{searchService}
GROUP BY pz.cfg_id, pz.attr_type, PZ.REPORT_TIME,pz.service)) a) group by attr_type, REPORT_TIME,service ) DJ_CFG_ATTR_STAT_LOG_HOUR
ORDER BY ${page.orderBy}

SELECT

	
		${page.fields}
	
	
		ASUM,BSUM,REPORT_TIME,SERVICE,SRC_PROVINCE,SRC_CITY
	

FROM (SELECT
SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM,
SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME,
PZ.SERVICE,
pz.SRC_PROVINCE,pz.SRC_CITY
FROM
DJ_SRCIP_DOMESTIC_REPORT PZ
GROUP BY PZ.SRC_PROVINCE,pz.SRC_CITY,
PZ.SERVICE, PZ.REPORT_TIME
) DJ_SRCIP_DOMESTIC_REPORT

	
		AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
	
	
		AND SRC_PROVINCE =#{searchSrcProvince}
	
	
		AND SRC_CITY =#{searchSrcCity}
	
	
		AND SERVICE =#{searchService}
	


	
		ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,DEST_COUNTRY,SERVICE
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.SERVICE, pz.DEST_COUNTRY FROM DJ_DESTIP_COUNTRY_REPORT PZ GROUP BY PZ.DEST_COUNTRY, PZ.SERVICE, PZ.REPORT_TIME ) DJ_DESTIP_COUNTRY_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND DEST_COUNTRY =#{searchDestCountry}
AND SERVICE =#{searchService}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,SERVICE,LWHH
FROM (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME, PZ.lwhh,pz.service FROM DJ_LWHH_REPORT PZ GROUP BY PZ.lwhh,pz.service, PZ.REPORT_TIME ) DJ_LWHH_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND service=#{searchService}
AND lwhh=#{searchLwhh}
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,absum,REPORT_TIME,SERVICE,TAG
FROM ( SELECT tag,REPORT_TIME, sum(asum) asum, sum(bsum) bsum, SUM(absum) absum,service FROM (select tag, asum, bsum, absum, REPORT_TIME,service from (select tag, REPORT_TIME,service, asum, bsum, decode(asum, 0, bsum, asum) absum from (SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM,
PZ.REPORT_TIME, pz.cfg_id, pz.tag,pz.service FROM dj_pz_tag_report PZ
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND tag in(${searchTag})
and service=#{searchService}
GROUP BY pz.cfg_id, pz.tag, PZ.REPORT_TIME,pz.service)) a) group by tag, REPORT_TIME,service
) DJ_CFG_TAG_STAT_LOG_HOUR
ORDER BY ${page.orderBy}

SELECT
${page.fields}
ASUM,BSUM,REPORT_TIME,SERVICE,ENTRANCE_ID
FROM ( SELECT SUM(CASE WHEN PZ.ACTIVE_SYS = 4 THEN SUM ELSE 0 END) ASUM, SUM(CASE WHEN PZ.ACTIVE_SYS = 2 THEN SUM ELSE 0 END) BSUM, PZ.REPORT_TIME REPORT_TIME, PZ.ENTRANCE_ID ENTRANCE_ID, pz.service FROM DJ_ENTRANCE_REPORT PZ GROUP BY PZ.REPORT_TIME,pz.service, PZ.ENTRANCE_ID ) DJ_ENTRANCE_REPORT
AND REPORT_TIME >= to_date(#{searchReportStartTime},'yyyy-MM-dd HH24:mi:ss')
AND REPORT_TIME < to_date(#{searchReportEndTime},'yyyy-MM-dd HH24:mi:ss')
AND service=#{searchService}
AND ENTRANCE_ID=#{searchEntraceId}
ORDER BY ${page.orderBy}
